INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (42, 'refeicao', '250 kcal', '1 xícara de gelatina sabor morango e limão com leite condensado semidesnatado (6% gordura, Piracanjuba) e um caixão de uva vitória (uva preta sem semente)', 'P: 4.7g | C: 56.5g | G: 2.1g', 250.0, 'green', 'Lanche da Tarde', '2026-09-12T22:52:39.059595', 7, 4.7, 56.5, 2.1, 'Essa refeição é rica em açúcares simples e possui poucas proteínas e fibras. Para melhorar o perfil nutricional e aumentar a saciedade, experimente trocar a gelatina comum por gelatina zero e o leite condensado por iogurte natural desnatado.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (44, 'refeicao', '175 kcal', 'Uma xícara de gelatina com leite condensado desnatado ', 'P: 4.5g | C: 39g | G: 0.1g', 175.0, 'green', 'Ceia/Lanche Noturno', '2026-09-12T23:46:35.470571', 8, 4.5, 39.0, 0.1, 'Para evitar picos de glicemia antes de dormir, considere utilizar gelatina zero açúcar e combinar com uma fonte de proteína como iogurte grelha desnatado em vez de leite condensado.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
