INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (48, 'refeicao', '440 kcal', 'Dois pão de forma com ovo mechido e meia colher de sopa de maionese e de bebida 200 ml de whey shark pro 23g de proteína ', 'P: 39g | C: 28.5g | G: 18g', 440.0, 'green', 'Café da Manhã', '2026-09-13T14:46:48.118921', 8, 39.0, 28.5, 18.0, 'Esta refeição possui um excelente aporte de proteínas, ótimo para recuperação muscular e saciedade. Para torná-la ainda mais nutritiva, substitua o pão tradicional por pão 100% integral para adicionar fibras e inclua vegetais aos ovos mexidos.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (49, 'refeicao', '360 kcal', 'Caldo de mandioca e cenoura com frango desfiado ', 'P: 26g | C: 42g | G: 8g', 360.0, 'green', 'Almoço', '2026-09-13T16:41:26.404837', 10, 26.0, 42.0, 8.0, 'Uma refeição nutritiva e reconfortante! A mandioca fornece carboidratos de boa qualidade e o frango garante bom aporte proteico. Para torná-la ainda mais completa em fibras e micronutrientes, experimente adicionar couve picada ao caldo ou acompanhar com uma salada verde.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (50, 'refeicao', '740 kcal', 'Duas cumbuca de caldo de mandioca com cenoura com frango desfiado e pedacinho de calabresa e meio copo de suco de uva Maguary e um pão francês ', 'P: 33g | C: 105g | G: 19g', 740.0, 'green', 'Almoço', '2026-09-13T19:34:20.534000', 8, 33.0, 105.0, 19.0, 'Esta refeição apresenta alto teor de carboidratos pela combinação de mandioca, pão e suco. Para um melhor equilíbrio glicêmico e maior saciedade, experimente adicionar folhas verdes ao caldo e evitar o acompanhamento de pão quando o prato principal já for rico em amido.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (51, 'refeicao', '74 kcal', 'Uma cápsula dolce gusto sabor Nescau ', 'P: 1.8g | C: 12g | G: 2g', 74.0, 'green', 'Lanche da Tarde', '2026-09-13T19:35:12.006951', 8, 1.8, 12.0, 2.0, 'Por ser uma bebida líquida rica em carboidratos simples e com pouca fibra, a absorção é rápida e dá pouca saciedade. Experimente associar a uma fonte de fibras ou proteína, como algumas castanhas ou uma fruta.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (53, 'refeicao', '800 kcal', 'Lanche X-Salada com catupiry e chegar e 1 copo de coca cola zero', 'P: 37g | C: 40g | G: 53g', 800.0, 'green', 'Jantar', '2026-09-12T21:59:11.822306', 7, 37.0, 40.0, 53.0, 'Esta refeição é bastante calórica e rica em gorduras saturadas devido aos queijos e molhos. Tente equilibrar reduzindo os queijos processados e priorizando carnes mais magras nas próximas refeições.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (54, 'refeicao', '425 kcal', '1 xícara de Gelatina com leite condensado semidesnatado (6% gordura Piracamjuba). Meio copo de 300ml de leite com 2 colheres de Nescau e 6 bolachas de maisena', 'P: 11.5g | C: 77g | G: 7.5g', 425.0, 'green', 'Ceia/Lanche Noturno', '2026-09-12T22:03:35.691195', 7, 11.5, 77.0, 7.5, 'Esta refeição noturna apresenta elevada carga glicêmica devido aos açúcares refinados da gelatina, leite condensado, Nescau e biscoito. Para um sono mais reparador e melhor controle glicêmico, prefira opções com mais fibras e proteínas de lenta absorção, como iogurte natural com sementes ou aveia.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (55, 'refeicao', '355 kcal', '1 pão francês com ovo mexido e 1 copo de Whey (Shark Pro 23g proteína)', 'P: 33g | C: 32.5g | G: 10g', 355.0, 'green', 'Café da Manhã', '2026-09-13T22:05:59.301656', 7, 33.0, 32.5, 10.0, 'Excelente aporte proteico para o café da manhã. Para deixar a refeição ainda mais completa e melhorar o trânsito intestinal, inclua uma porção de fruta com fibras, como mamão ou kiwi.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
