INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (58, 'refeicao', '525 kcal', '1 tigela de caldo de mandioca com cenoura, frango desfiado e calabresa e um copo de suco uva Maguari e 3 fatias de pão francês (cortado em tiras de torrada) ', 'P: 23g | C: 74g | G: 15.2g', 525.0, 'green', 'Almoço', '2026-09-13T22:13:06.805187', 7, 23.0, 74.0, 15.2, 'Esta refeição possui uma carga elevada de carboidratos devido à combinação de mandioca, pão e suco. Para um melhor equilíbrio nutricional, experimente substituir o suco adoçado por água ou suco integral diluído, e aumente a proporção de frango desfiado em relação à calabresa para reduzir as gorduras saturadas.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (59, 'refeicao', '480 kcal', 'Um bolo de pote recheado sabor chocolate alpino ', 'P: 6g | C: 65g | G: 22g', 480.0, 'green', 'Ceia/Lanche Noturno', '2026-09-13T22:14:45.518421', 8, 6.0, 65.0, 22.0, 'Por ser uma opção com alto teor de açúcares e gorduras consumida à noite, tente reservar estes doces para momentos pontuais durante o dia para evitar picos glicêmicos antes de dormir.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (60, 'refeicao', '580 kcal', '1 bolo de pote sabor kinder Bueno ', 'P: 8g | C: 65g | G: 32g', 580.0, 'green', 'Ceia/Lanche Noturno', '2026-09-13T22:15:07.695882', 7, 8.0, 65.0, 32.0, 'Por ser uma opção rica em açúcares e gorduras consumida perto do horário de dormir, pode impactar a qualidade do sono e a digestão. Dê preferência a consumir doces mais calóricos durante o dia e opte por uma ceia mais leve, como iogurte proteico ou chá com sementes.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
