INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (79, 'refeicao', '300 kcal', '200ml de whey shark pro sabor banana, aveia com cookies. ', 'P: 28g | C: 30g | G: 7g', 300.0, 'green', 'Lanche da Tarde', '2026-09-15T18:07:57.364259', 7, 28.0, 30.0, 7.0, 'Esta refeição é excelente para o pós-treino ou lanche proteico. Para aumentar a saciedade, priorize a aveia integral e monitore a quantidade de cookies para controlar o consumo de açúcares simples.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (80, 'refeicao', '625 kcal', '1 lanche caseiro de hambúrguer de 150gr, 1 fatia de queijo chedar e folhas de rúculas e meio copo de suco de abacaxi maguari ', 'P: 40g | C: 40g | G: 31g', 625.0, 'green', 'Ceia/Lanche Noturno', '2026-09-15T18:11:08.927142', 7, 40.0, 40.0, 31.0, 'Como é uma refeição noturna, o alto teor de gorduras e carboidratos pode desacelerar a digestão e impactar a qualidade do sono. Para a ceia, prefira carnes mais magras, evite bebidas com açúcar adicionado e considere pães integrais.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (81, 'exercicio', '-280 kcal', 'Musculação (Peito e Tríceps) (60 min - Moderada)', 'MET calculado: 5.0', 280.0, 'orange', 'Exercício', '2026-09-15T18:13:38.538239', 7, 0.0, 0.0, 0.0, 'Consuma uma fonte de proteína de boa qualidade e mantenha-se hidratado após o treino para otimizar a síntese proteica e a recuperação dos músculos peitorais e tríceps.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (82, 'refeicao', '425 kcal', 'Menu Perdigão congelado sabor Carne Moída com Purê de Batata e Arroz com Brócolis 300g e uma banana nanica e uma salada de rúcula e meia latinha de energético Bally zero açúcar sabor tropical', 'P: 17.5g | C: 65.5g | G: 10.4g', 425.0, 'green', 'Almoço', '2026-09-16T18:20:07.862850', 7, 17.5, 65.5, 10.4, 'A refeição possui um bom aporte de fibras da salada e da fruta, mas pratos congelados ultraprocessados costumam ter alto teor de sódio e conservantes. Tente priorizar alimentos frescos no almoço e evite energéticos junto às refeições para não atrapalhar a absorção de nutrientes.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
