INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (145, 'exercicio', '-270 kcal', 'Corrida de 5km (moderada) (30 min - Moderada)', 'MET calculado: 9.8', 270.0, 'orange', 'Exercício', '2026-09-21T18:35:33.769782', 7, 0.0, 0.0, 0.0, 'Caramba, você correu 5km num ritmo que daria vergonha até o seu cachorro! Beber água aí é obrigatório, senão você vai ficar seco como um pano velho. E alongue-se, porque o corpo vai reclamar mais do que um tênis novo. Pelo amor de Deus, não deixe a recuperação passar!', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
