INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (157, 'exercicio', '-91.4 kcal', 'Corrida na esteira (30 min - Moderada)', 'MET calculado: 7.0', 91.4, 'orange', 'Exercício', '2026-09-23T20:20:55.378555', 8, 0.0, 0.0, 0.0, 'Beba água regularmente durante o treino e consuma uma refeição balanceada com proteínas e carboidratos complexos nos 30 minutos seguintes à corrida para otimizar a recuperação muscular.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (159, 'refeicao', '237.0 kcal', '33g de whey concentrado com 200ml de leite ', 'P: 33.4g | C: 10.6g | G: 7.6g', 237.0, 'green', 'Refeição', '2026-09-23T22:55:15.645480', 8, 33.4, 10.6, 7.6, 'A combinação de whey concentrado com leite integral oferece uma fonte completa de proteínas (~33g) com aporte equilibrado de carboidratos e gorduras. O whey concentrado proporciona alta densidade proteica, enquanto o leite integral complementa com lipídios saud Quase e lactose natural, sendo ideal para suplementação pós-treino ou como base de shakes nutritivos.', '{"vegetais": "", "proteinas": "", "fibras": "", "acucar": "", "ultraprocessados": ""}', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (160, 'refeicao', '225.0 kcal', '6 biscoito de maisena marilan', 'P: 2.5g | C: 30.0g | G: 8.0g', 225.0, 'green', 'Refeição', '2026-09-23T23:09:31.741309', 8, 2.5, 30.0, 8.0, 'Os biscoitos de maisena possuem perfil calórico moderado devido à sua composição de farinha de trigo e açúcar. Considere que 6 unidades representam aproximadamente 65g no total. A fibra é baixa, sendo predominante carboidratos simples e gorduras saturadas. Para controle calórico, prefira consumir porções menores ou combinar com alimentos ricos em proteína e fibras. A variação dependerá do tamanho exato de cada biscoito e da marca específica.', '{"vegetais": "", "proteinas": "", "fibras": "", "acucar": "", "ultraprocessados": ""}', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (161, 'refeicao', '695.0 kcal', 'Duas colheres de arroz de arroz com uma concha de feijão 
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (162, 'refeicao', '361.0 kcal', '33gramas de whey concentrado e 4 colheres de sopa de iogurte natural
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (163, 'refeicao', '383.0 kcal', '33grama de whey concentrado e 5 colheres de sopa de iogurte natural e um pão com uma colher de sopa de maionese heins ', 'P: 32.9g | C: 37.2g | G: 11.0g', 383.0, 'green', 'Refeição', '2026-09-24T06:49:49.460481', 8, 32.9, 37.2, 11.0, 'Murilo, essa refeição oferece um ótimo aporte proteico para estímulo da síntese muscular. Para otimizar o perfil glicêmico e a saciedade, considere futuramente optar por pães de grãos integrais ou adicionar fibras ao iogurte, como psyllium ou chia.', '{"vegetais": "", "proteinas": "", "fibras": "", "acucar": "", "ultraprocessados": ""}', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (164, 'exercicio', '-522 kcal', 'Musculação de alta intensidade (Quadríceps, Ombros e Abdômen) (60 min - Alta/Vigorosa)', 'MET calculado: 6', 522.0, 'orange', 'Exercício', '2026-09-24T06:51:09.463357', 8, 0.0, 0.0, 0.0, 'Murilo, treinos de alta intensidade que recrutam grandes grupamentos musculares, como os quadríceps, promovem alto estresse metabólico e microlesões teciduais. Para otimizar a síntese proteica e a recuperação do glicogênio muscular, garanta uma ingestão adequada de proteínas e carboidratos nas próximas horas, além de hidratação contínua e descanso suficiente antes de submeter esses músculos a um novo estímulo máximo.', NULL, NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (165, 'refeicao', '566.0 kcal', 'Duas colheres de arroz de arroz uma colher de arroz de farofa temperada e uma porção de carne a brase, (carne vermelha cozida com um pouco de molho) e uma banana ', 'P: 55.7g | C: 59.6g | G: 32.9g', 566.0, 'green', 'Refeição', '2026-09-24T13:33:34.227305', 8, 55.7, 59.6, 32.9, 'A carne à brasa representa cerca de 58% das calorias totais (330 kcal) devido à sua composição rica em gordura, sendo o principal motor energético da refeição. O arroz contribui com aproximadamente 13% (78 kcal) e a banana com 18% (105 kcal), fornecendo carboidratos complexos e energia rápida. A farofa adiciona 9% das calorias (53 kcal) através de amidos e pequenas quantidades de gordura vegetal. O perfil macronutricional resultante é rico em proteína (55,7g) e gordura (32,9g), com fibra total estimada em 3,3g, indicando uma refeição equilibrada para um adulto ativo.', '{"vegetais": "", "proteinas": "", "fibras": "", "acucar": "", "ultraprocessados": ""}', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (166, 'refeicao', '198.3 kcal', '1 pão de forma com apresentado e queijo mussarela e 1 xícara de café lungo expresso Dolce Gusto (sem açúcar) ', 'P: 9.7g | C: 13.6g | G: 6.8g', 198.3, 'green', 'Refeição', '2026-09-23T18:56:05.525597', 7, 9.7, 13.6, 6.8, 'A refeição totaliza aproximadamente 200 kcal, sendo o queijo mussarela o principal contribuinte energético (quase metade das calorias). O café contribui minimamente com calorias devido à sua natureza quase zero-calórica. O pão de forma representa a maior parte dos carboidratos e fibras. Como a quantidade de queijo não foi especificada, foi utilizada uma estimativa conservadora de 35g (porção típica de sanduíche). Para obter valores precisos, recomenda-se consultar o rótulo do produto ou pesar o queijo antes do consumo.', '{"vegetais": "", "proteinas": "", "fibras": "", "acucar": "", "ultraprocessados": ""}', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (167, 'refeicao', '622.5 kcal', '2 colheres de arroz de arroz, 1 concha de feijão e seleta de legumes (brócolis, cenoura, couve flor e vagem) e 1 filé pequeno de frango grelhado', 'P: 72.1g | C: 57.6g | G: 8.4g', 622.5, 'green', 'Refeição', '2026-09-23T19:04:21.684603', 7, 72.1, 57.6, 8.4, 'A refeição apresenta excelente equilíbrio entre proteínas magras, carboidratos complexos e fibras dietéticas. O frango grelhado é a fonte principal de proteína, enquanto o arroz e o feijão fornecem energia sustentável e complexidade nutricional. Os vegetais complementam a dieta com micronutrientes essenciais e aumentam o aporte de fibras solúveis, favorecendo a saúde gastrointestinal.', '{"vegetais": "", "proteinas": "", "fibras": "", "acucar": "", "ultraprocessados": ""}', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (168, 'refeicao', '189.0 kcal', 'Uma porção de 1/4 de abacaxi e um pão de queijo médio 
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (169, 'refeicao', '240.0 kcal', 'Um pedaço de 100g bolo de paçoca ', 'P: 3.5g | C: 46.0g | G: 6.5g', 240.0, 'green', 'Refeição', '2026-09-25T10:45:21.810012', 8, 3.5, 46.0, 6.5, 'O bolo de paçoca é predominantemente composto por farinha de mandioca, que fornece a maior parte das calorias como carboidratos complexos. A adição de açúcar e gordura durante a preparação eleva significativamente o índice calórico, tornando-o uma refeição densa em energia. Para quem monitora a ingestão calórica, é importante considerar que 100g representa aproximadamente 24% das necessidades diárias de energia de um adulto médio, sendo recomendável controlar a porção e preferir versões menos processadas.', '{"vegetais": "", "proteinas": "", "fibras": "", "acucar": "", "ultraprocessados": ""}', NULL, NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (170, 'refeicao', '382.0 kcal', 'Um colher de arroz de arroz e meia concha de feijão com salada de alface e um bife de carne vermelha assado
