INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (182, 'refeicao', '63.0 kcal', 'Uma colher de doce de leite ', 'P: 1.2g | C: 11.4g | G: 1.4g', 63.0, 'green', 'Refeição', '2026-10-06T18:43:19.010561', 8, 1.2, 11.4, 1.4, 'Os doce de leite são alimentos ultraprocessados que contribuem significativamente para o consumo excessivo de açúcar. Evite consumir grandes quantidades diariamente. Prefira opções naturais como frutas frescas como alternativa mais saudável para satisfazer o desejo de sabor.', '{"vegetais": "ruim", "proteinas": "razoavel", "fibras": "ruim", "acucar": "ruim", "ultraprocessados": "ruim"}', 'Alta', '[{"nome": "Doce de Leite", "nome_original": "doce de leite", "quantidade_original": "1", "unidade_original": "colher de doce de leite", "peso_g": 20, "kcal": 63, "prot": 1.2, "carb": 11.4, "gord": 1.4, "confianca": "Alta", "fonte": "Base de referência", "metodo_medida": "especifica"}]') ON CONFLICT (id) DO NOTHING;
INSERT INTO logs (id, tipo, titulo, descricao, detalhes, calorias, cor, tag, data_hora, usuario_id, proteinas_g, carboidratos_g, gorduras_g, dica_ia, qualidade_json, nivel_confianca, itens_detalhados_json) VALUES (183, 'refeicao', '543.0 kcal', 'Pão de forma com queijo mussarela, 2 torradas integrais, uma colher de chá de doce de leite. Um café de cápsula. ', 'P: 12.4g | C: 88.2g | G: 15.8g', 543.0, 'green', 'Refeição', '2026-10-06T22:29:20.510748', 7, 12.4, 88.2, 15.8, 'Priorize alimentos integrais e ricos em fibras. Escolha queijos com menor teor de gordura e maior contenção de proteínas. Reduza o consumo de açúcares adicionados e opt por opções menos processadas sempre que possível.', '{"vegetais": "boa", "proteinas": "boa", "fibras": "boa", "acucar": "ruim", "ultraprocessados": "m\u00e9dia"}', 'Média', '[{"nome": "Pão de queijo assado", "nome_original": "Pão de forma com queijo mussarela", "quantidade_original": "1", "unidade_original": "porcao", "peso_g": 50, "kcal": 181.5, "prot": 2.5, "carb": 17.1, "gord": 12.3, "confianca": "Média", "fonte": "Base de referência", "metodo_medida": "estimativa_ia"}, {"nome": "Torrada pão francês", "nome_original": "2 torradas integrais", "quantidade_original": "2", "unidade_original": "porcao", "peso_g": 90, "kcal": 339.3, "prot": 9.5, "carb": 67.1, "gord": 3, "confianca": "Média", "fonte": "Base de referência", "metodo_medida": "estimativa_ia"}, {"nome": "Doce de Leite", "nome_original": "uma colher de chá de doce de leite", "quantidade_original": "1", "unidade_original": "colher de chá", "peso_g": 7, "kcal": 22.1, "prot": 0.4, "carb": 4, "gord": 0.5, "confianca": "Alta", "fonte": "Base de referência", "metodo_medida": "especifica"}]') ON CONFLICT (id) DO NOTHING;
